local a={}a.__index=a;function a.new(b,c)return setmetatable({windowMs=b or 3600000,intervalMs=c or 5000,points={},lastSample=nil},a)end;function a:add(d,e)if type(d)~="number"then return end;e=e or os.epoch("utc")if self.lastSample and e-self.lastSample<self.intervalMs then return end;self.lastSample=e;self.points[#self.points+1]={time=e,value=d}self:prune(e)end;function a:prune(f)f=f or os.epoch("utc")local g=f-self.windowMs;while#self.points>0 and self.points[1].time<g do table.remove(self.points,1)end end;function a:getPoints()self:prune()return self.points end;function a:getRate()local h=self:getPoints()if#h<2 then return nil end;local i=h[1]local j=h[#h]local k=(j.time-i.time)/1000;if k<=0 then return nil end;return(j.value-i.value)/k end;return a
